[7810]=[=[{o="Speak with Short John Mithril in the Stranglethorn Arena.",d="There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!",c="Arr Me Hearty! Gaining one Trinket be not enough to make ye master of the Arena! Now tis the time to truly prove your steel.",r={xp=550},sd={i=18706,by={{"Found in",{"Arena Treasure Chest"},1}},m=1434,at={30.5,47.9}},k=true}]=],
