[8926]=[=[{o="Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge.",d="You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.",p="You're ready to perform the trade?",c="You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.",r={it={{22106,1,"Feralheart Belt",3,"inv_belt_15"},{22110,1,"Feralheart Gloves",4,"inv_gauntlets_17"}},xp=19900},k=true}]=],
[8929]=[=[{o="Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.",d="Well, nothing left for us to do but try out the goblin's invention.  Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and find out whatever Anthion knew.",c="Deliana had you contact me? I'll do my best to help you, but first I must ask a great favor of you.",r={m=19800,xp=6600},k=true}]=],
[8930]=[=[{o="Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.",d="Very well, <name>.  All that remains is to put the goblin's invention to the test.  Word has it that Anthion was slain by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and see if, indeed, you can speak with the dead!",c="Mokvar had you contact me? I'll do my best to help you, but first I must ask a great favor of you.",r={m=19800,xp=6600},k=true}]=],
[8931]=[=[{o="Bring a Beaststalker's Belt and a set of Beaststalker's Gloves to Deliana in Ironforge.",d="You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me an ordinary belt and a set of gloves that you wish to upgrade.",p="You're ready to perform the trade?",c="You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.",r={it={{22010,1,"Beastmaster's Belt",3,"inv_belt_28"},{22015,1,"Beastmaster's Gloves",4,"inv_gauntlets_10"}},xp=19900},k=true}]=],
